// 全库：葡语目录/文件名 → 中文；正文标签与 category 中文化
import fs from "fs";
import path from "path";
import os from "os";

const DRY = process.argv.includes("--dry");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const OUT = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out"
);

const PT_SEG =
  /^(padrão técnico|padrão de código|padrao_tecnico|estrutura de código|estrutura de projeto|projeto de software|correção de bug|correcao de bug|notas técnicas de frontend|notas técnicas|bug conhecido|programa)$/i;

const SEG_TO_CN = {
  "padrão técnico": "技术模式",
  "padrão de código": "技术模式",
  padrao_tecnico: "技术模式",
  "estrutura de código": "代码结构",
  "estrutura de projeto": "项目结构",
  "projeto de software": "软件项目",
  "correção de bug": "缺陷修复",
  "correcao de bug": "缺陷修复",
  "notas técnicas de frontend": "前端技术说明",
  "notas técnicas": "技术说明",
  "bug conhecido": "已知缺陷",
  programa: "软件项目",
};

const PT_FILE =
  /Correção|Correcao|Refatoração|Configuração|Migração|Substituição|adição de|correcao_|migração|padrão|painéis|diretório|sessão|validação|atualização|espaço|navegação|parâmetro|permissão|reconhecimento|dicionário|mapeamento|anúncio|contrato|telefone|imóveis|estacionamento|trabalhador|certificados|supervisão|reembolso|verificação|versão|formulário|funcionalidade|sub-tabelas|filtro bizstate|listas imobiliárias|no diretório|arquivos Vue|concluíram|substituído|removidos|sessão Cursor/i;

const LABELS = [
  [/## Causa raiz/gi, "## 问题根因"],
  [/## Solução/gi, "## 解决方案"],
  [/## Verificação e origem/gi, "## 验证与归属"],
  [/## Descrição/gi, "## 描述"],
  [/## Fatos principais/gi, "## 关键事实"],
  [/## Problema/gi, "## 问题"],
  [/## Contexto/gi, "## 背景"],
  [/\bEvidência:/gi, "验证证据:"],
  [/\bFonte:/gi, "来源:"],
  [/\bProva:/gi, "验证证据:"],
  [/\bArquivos:/gi, "涉及文件:"],
  [/\bProjeto:/gi, "所属项目:"],
  [/\*\*Category:\*\* Bug conhecido/gi, "**分类:** 已知缺陷"],
  [/\*\*Category:\*\* Padrão técnico/gi, "**分类:** 技术模式"],
];

const CAT_MAP = {
  "padrão técnico": "技术模式",
  "Padrão técnico": "技术模式",
  "padrão de código": "技术模式",
  "estrutura de código": "代码结构",
  "estrutura de projeto": "项目结构",
  "projeto de software": "软件项目",
  "correção de bug": "缺陷修复",
  "bug conhecido": "已知缺陷",
  "Bug conhecido": "已知缺陷",
  "notas técnicas de frontend": "前端技术说明",
  "notas técnicas": "技术说明",
};

function bodyOf(raw) {
  return raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g, "").trim();
}

function patchContent(raw) {
  let out = raw;
  for (const [re, rep] of LABELS) out = out.replace(re, rep);
  const m = out.match(/<!-- MEMORY_FIELDS\s*([\s\S]*?)-->/);
  if (m) {
    try {
      const j = JSON.parse(m[1].trim());
      if (j.category && CAT_MAP[j.category]) j.category = CAT_MAP[j.category];
      else if (j.category && /padrão|estrutura|projeto|conhecido|notas/i.test(String(j.category)))
        j.category = "技术模式";
      out = out.replace(m[0], `<!-- MEMORY_FIELDS\n${JSON.stringify(j, null, 2)}\n-->`);
    } catch {}
  }
  return out;
}

function cnBasename(name, raw) {
  const base = name.replace(/\.md$/i, "");
  if (!PT_FILE.test(base) && !/[ãõáéíóúçÃÕÁÉÍÓÚÇ]/.test(base)) return name;
  const body = bodyOf(raw);
  const h1 = (body.match(/^#\s+(.+)$/m) || [])[1];
  if (h1 && /[\u4e00-\u9fff]/.test(h1)) {
    const slug = h1
      .replace(/[\\/:*?"<>|]/g, "")
      .slice(0, 80)
      .trim();
    return slug + ".md";
  }
  const h1any = (body.match(/^#\s+(.+)$/m) || [])[1];
  if (h1any && h1any.length < 100) {
    return (
      h1any
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^\w\u4e00-\u9fff\- ]+/g, " ")
        .trim()
        .slice(0, 60)
        .replace(/\s+/g, "_") + ".md"
    );
  }
  return base
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "_")
    .slice(0, 60) + ".md";
}

function targetRel(rel, raw) {
  const parts = rel.split("/");
  const newParts = parts.map((seg, i) => {
    if (i === parts.length - 1) return cnBasename(seg, raw);
    const key = Object.keys(SEG_TO_CN).find((k) => seg.toLowerCase() === k.toLowerCase() || seg === k);
    if (key) return SEG_TO_CN[key];
    if (PT_SEG.test(seg)) return "技术模式";
    return seg;
  });
  return newParts.join("/");
}

function needsFix(rel, raw) {
  if (rel.split("/").some((s) => PT_SEG.test(s))) return true;
  const base = path.basename(rel);
  if (PT_FILE.test(base) || /[ãõáéíóúçÃÕÁÉÍÓÚÇ]/.test(base)) return true;
  if (/\b(Causa raiz|Evidência:|Padrão técnico|Bug conhecido|Category:\*\* Bug)/i.test(raw)) return true;
  return false;
}

const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && !e.name.startsWith(".")) files.push(p);
  }
}
walk(MEM);

const actions = [];
let moved = 0;
let patched = 0;
let quarantined = 0;
const QUAR = path.join(OUT, "dedupe-quarantine", "pt-full-" + new Date().toISOString().replace(/[:.]/g, "-"));

for (const abs of files) {
  const rel = path.relative(MEM, abs).replace(/\\/g, "/");
  let raw = fs.readFileSync(abs, "utf8");
  if (!needsFix(rel, raw)) continue;
  const patchedRaw = patchContent(raw);
  const destRel = targetRel(rel, patchedRaw);
  const destAbs = path.join(MEM, destRel);

  if (destRel === rel && patchedRaw === raw) continue;

  if (destRel === rel) {
    actions.push({ action: "patch", rel });
    if (!DRY) {
      fs.writeFileSync(abs, patchedRaw, "utf8");
      patched++;
    }
    continue;
  }

  if (fs.existsSync(destAbs) && path.resolve(destAbs) !== path.resolve(abs)) {
    const ex = fs.readFileSync(destAbs, "utf8");
    if (bodyOf(ex).length >= bodyOf(patchedRaw).length) {
      actions.push({ action: "quarantine", from: rel, dest: destRel });
      if (!DRY) {
        const q = path.join(QUAR, rel);
        fs.mkdirSync(path.dirname(q), { recursive: true });
        fs.renameSync(abs, q);
        quarantined++;
      }
      continue;
    }
    if (!DRY) fs.unlinkSync(destAbs);
  }

  actions.push({ action: "move", from: rel, to: destRel });
  if (!DRY) {
    fs.mkdirSync(path.dirname(destAbs), { recursive: true });
    fs.writeFileSync(destAbs, patchedRaw, "utf8");
    if (path.resolve(abs) !== path.resolve(destAbs)) fs.unlinkSync(abs);
    moved++;
  }
}

// 删除空葡语目录
function rmEmpty(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) rmEmpty(p);
  }
  const left = fs.readdirSync(d);
  const onlyDot = left.every((x) => x.startsWith("."));
  if (left.length === 0 || (onlyDot && left.length <= 2)) {
    const rel = path.relative(MEM, d).replace(/\\/g, "/");
    if (rel && rel.split("/").some((s) => PT_SEG.test(s) || /padrão|estrutura|correção|conhecido|padrao/i.test(s))) {
      if (!DRY) {
        for (const x of left) fs.unlinkSync(path.join(d, x));
        fs.rmdirSync(d);
      }
    }
  }
}
if (!DRY) rmEmpty(MEM);

fs.writeFileSync(
  path.join(OUT, "migrate-all-portuguese-log.json"),
  JSON.stringify({ at: new Date().toISOString(), dry: DRY, moved, patched, quarantined, actions: actions.length, sample: actions.slice(0, 40) }, null, 2)
);
console.log(DRY ? "DRY" : "DONE", { moved, patched, quarantined, actions: actions.length });

