// 全库记忆正文：葡语 → 简体中文（保留 MEMORY_FIELDS 与代码块）
import fs from "fs";
import path from "path";
import os from "os";

const DRY = process.argv.includes("--dry");
const LIMIT = (() => {
  const i = process.argv.indexOf("--limit");
  return i >= 0 ? parseInt(process.argv[i + 1], 10) : Infinity;
})();
const CONC = (() => {
  const i = process.argv.indexOf("--concurrency");
  return i >= 0 ? parseInt(process.argv[i + 1], 10) : 3;
})();

const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const OUT = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out"
);
const PROGRESS = path.join(process.env.TEMP, "translate-pt-bodies-progress.json");

const PT_STRONG =
  /[ãõáéíóúçÃÕÁÉÍÓÚÇ]|\b(não|não|sessão|evidência|evidencia|fonte|descrição|descri|solução|verificação|verificacao|causa raiz|fatos principais|arquivos vue|dos quais|concluíram|concluiram|substituído|substituido|removidos|migração|migracao|diretório|diretorio|colunas|botão|botao|diálogo|dialogo|contrato|locação|locacao|gestão|gestao|iniciativas|monetário|monetario|devem|deve|foram|está|esta|este|estes|pelo|pela|pelos|pelas|uma|um|uns|umas|nos|nas|nos|para o|para a|com o|com a|no diretório|no diretorio|sessão cursor|extraído|extraido|prova:|projeto:|arquivos:|evidência:|fonte:)\b/i;

const REFUSE = /您好|有什么|不小心|键盘|随时告诉|问号/;

function split(raw) {
  const m = raw.match(/^(.*)(<!-- MEMORY_FIELDS[\s\S]*?-->\s*)$/s);
  if (!m) return { body: raw.trimEnd(), fields: "" };
  return { body: m[1].trimEnd(), fields: m[2] };
}

function needsTranslate(body) {
  if (!body.trim()) return false;
  if (PT_STRONG.test(body)) return true;
  const words = body.split(/\s+/).filter(Boolean);
  const ptHits = words.filter((w) =>
    /^(de|da|do|para|com|em|no|na|os|as|que|por|se|ao|à|dos|das|nos|nas|um|uma|uns|umas|ser|está|são|foi|foram|tem|têm|mais|como|quando|onde|sobre|entre|após|antes|sem|também|ainda|já|não|nao|você|voce|usuário|usuario|página|pagina|lista|arquivo|função|funcao|módulo|modulo|componente|implementado|corrigido|adicionado|removido|validado|configurado|atualizado|utilizado|obrigatório|obrigatorio|opcional|padrão|padrao|erro|teste|versão|versao)$/i.test(
      w.replace(/[^a-zA-Zà-úÀ-Ú]/g, "")
    )
  ).length;
  return ptHits >= 4;
}

async function translate(text) {
  const res = await fetch("http://127.0.0.1:3425/v1/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "auto/hy3",
      temperature: 0,
      max_tokens: 4096,
      messages: [
        {
          role: "system",
          content:
            "你是技术文档翻译器。将输入翻译成简体中文。保留 Markdown 结构、英文标识符、路径、文件名、代码片段、UUID、session id 不变。只输出译文正文，不要问候、不要解释。",
        },
        { role: "user", content: text },
      ],
    }),
  });
  if (!res.ok) throw new Error(`VLM ${res.status}`);
  const j = await res.json();
  const out = (j.choices?.[0]?.message?.content || "").trim();
  if (!out || REFUSE.test(out)) throw new Error("bad translation: " + out.slice(0, 80));
  if (!/[\u4e00-\u9fff]/.test(out) && PT_STRONG.test(out)) throw new Error("still PT");
  return out;
}

const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && !e.name.startsWith(".")) files.push(p);
  }
}
walk(MEM);

const done = new Set(fs.existsSync(PROGRESS) ? JSON.parse(fs.readFileSync(PROGRESS, "utf8")).done || [] : []);
const queue = [];
for (const abs of files) {
  const rel = path.relative(MEM, abs).replace(/\\/g, "/");
  if (done.has(rel)) continue;
  const raw = fs.readFileSync(abs, "utf8");
  const { body } = split(raw);
  if (needsTranslate(body)) queue.push({ abs, rel, raw });
}

console.log("queue", queue.length, "already", done.size, "DRY", DRY);

let ok = 0;
let fail = 0;
const log = [];
let idx = 0;

async function worker() {
  while (idx < queue.length && ok + fail < LIMIT) {
    const i = idx++;
    const { abs, rel, raw } = queue[i];
    const { body, fields } = split(raw);
    try {
      if (DRY) {
        console.log("WOULD", rel.slice(0, 70));
        ok++;
        continue;
      }
      const zh = await translate(body);
      const next = zh + (fields ? "\n\n" + fields : "") + (raw.endsWith("\n") ? "\n" : "");
      fs.writeFileSync(abs, next, "utf8");
      done.add(rel);
      fs.writeFileSync(PROGRESS, JSON.stringify({ at: new Date().toISOString(), done: [...done], ok, fail }, null, 2));
      ok++;
      if (ok % 10 === 0) console.log("progress", ok, "/", queue.length, rel.slice(0, 50));
    } catch (e) {
      fail++;
      log.push({ rel, err: String(e.message || e) });
      console.warn("FAIL", rel.slice(0, 50), e.message);
    }
  }
}

await Promise.all(Array.from({ length: CONC }, () => worker()));

fs.writeFileSync(path.join(OUT, "translate-pt-bodies-log.json"), JSON.stringify({ at: new Date().toISOString(), ok, fail, queue: queue.length, fails: log }, null, 2));
console.log("DONE ok", ok, "fail", fail);

